// What the kobold writes to the records, through its tools (tools.ts): the
// signal it is sorting, sorted and put in its place (one signal, never
// counted or merged with others), and a real problem it suggests behind two
// or more problems of one persona. Everything it writes says `by: kobold`
// until a person confirms it, and the store checks it like any write.
import { KOBOLD, SORTED_AS } from "@software-factory/core";
import { z } from "zod";
import { Refused } from "../refused.js";
import { Edit, newId } from "../records/edit.js";
import { place, placeSchema } from "../records/placing.js";
export const SORT_INPUT = {
    sortedAs: z
        .enum(SORTED_AS)
        .describe("need: something a person wants or struggles with; bug; question; update (a dependency's or a security update); unsure."),
    soundsLike: z
        .string()
        .nullable()
        .describe("The persona's id it sounds like, or null when it is not clear."),
    why: z
        .string()
        .trim()
        .min(1)
        .describe("Why it sounds like that persona, or why it is not clear."),
    place: placeSchema,
};
export const SUGGEST_INPUT = {
    title: z.string().trim().min(1).describe("The real problem, in a line."),
    description: z
        .string()
        .trim()
        .min(1)
        .describe("Why these problems point the same way, in two lines at most."),
    problems: z
        .array(z.string().min(1))
        .min(2)
        .describe("The ids of the persona's problems it sits behind."),
};
// The signal sorted and placed; what was done, in a line.
export function sortSignal(store, id, sort) {
    const edit = new Edit(store);
    const signal = edit.get("signals", id, "signal");
    if (sort.soundsLike !== null)
        edit.get("personas", sort.soundsLike, "persona");
    if (sort.place.to === "scene") {
        const story = edit.get("stories", sort.place.story, "story");
        if (sort.soundsLike !== story.persona)
            throw new Refused(`The story “${story.title}” is ${story.persona}'s: only a signal that sounds like ${story.persona} is evidence in it.`);
    }
    const sorted = {
        ...signal,
        sortedAs: sort.sortedAs,
        soundsLike: sort.soundsLike,
        why: sort.why,
        by: KOBOLD,
    };
    const done = place(edit, sorted, sort.place, KOBOLD);
    edit.save(store);
    return done;
}
// A real problem behind two or more problems of the persona, none of which
// has one yet; what was done, in a line.
export function suggestRealProblem(store, persona, suggest) {
    const edit = new Edit(store);
    const problems = [...new Set(suggest.problems)].map((p) => edit.get("problems", p, "problem"));
    for (const problem of problems) {
        if (problem.persona !== persona)
            throw new Refused(`The problem “${problem.title}” is not ${persona}'s: a real problem sits behind problems of one persona.`);
        if (problem.realProblem !== null)
            throw new Refused(`The problem “${problem.title}” has a real problem behind it already.`);
    }
    const real = edit.put("realProblems", {
        id: newId("real"),
        persona,
        title: suggest.title,
        description: suggest.description,
        by: KOBOLD,
    });
    for (const problem of problems)
        edit.put("problems", { ...problem, realProblem: real.id });
    edit.save(store);
    return `Suggested: “${real.title}”, behind ${String(problems.length)} problems. A person confirms it.`;
}
// How many problems of each persona have no real problem behind them.
export function freeProblems(store) {
    const free = new Map();
    for (const problem of store.list("problems"))
        if (problem.realProblem === null)
            free.set(problem.persona, (free.get(problem.persona) ?? 0) + 1);
    return free;
}
